<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Conway's Game of Life</title>
  <style>
    :root {
      --bg-color: #1a1a2e;
      --grid-line: #26264d;
      --cell-alive: #7b2cbf;
      --cell-border: #9d4edd;
      --text-color: #e0e0e0;
      --button-bg: #3c3c8a;
      --button-hover: #5a5abf;
      --button-active: #4d4db5;
    }

    body {
      font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
      background-color: var(--bg-color);
      color: var(--text-color);
      margin: 0;
      padding: 20px;
      display: flex;
      flex-direction: column;
      align-items: center;
      min-height: 100vh;
    }

    h1 {
      margin-top: 0;
      font-size: 2.5rem;
      text-align: center;
      color: #e0aaff;
      text-shadow: 2px 2px 4px rgba(0,0,0,0.5);
    }

    .game-container {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 15px;
    }

    #life {
      background-color: var(--bg-color);
      border: 2px solid #4a4a8a;
      box-shadow: 0 0 20px rgba(123, 44, 191, 0.3);
      cursor: crosshair;
    }

    .controls {
      display: flex;
      gap: 10px;
      flex-wrap: wrap;
      justify-content: center;
    }

    button {
      background-color: var(--button-bg);
      color: white;
      border: none;
      padding: 12px 24px;
      font-size: 1rem;
      border-radius: 8px;
      cursor: pointer;
      transition: all 0.2s ease;
      box-shadow: 0 3px 5px rgba(0,0,0,0.3);
    }

    button:hover {
      background-color: var(--button-hover);
      transform: translateY(-2px);
    }

    button:active {
      background-color: var(--button-active);
      transform: translateY(1px);
    }

    button.active {
      background-color: #5f288a;
      box-shadow: inset 0 3px 5px rgba(0,0,0,0.3);
    }

    .stats {
      display: flex;
      gap: 20px;
      font-size: 1rem;
      margin-top: 10px;
    }

    .instructions {
      max-width: 600px;
      text-align: center;
      color: #a8a8d4;
      font-size: 0.9rem;
      margin-top: 5px;
    }
  </style>
</head>
<body>
  <h1>Conway's Game of Life</h1>

  <div class="game-container">
    <canvas id="life" width="500" height="500"></canvas>

    <div class="controls">
      <button id="step">Step</button>
      <button id="play">Play / Pause</button>
      <button id="random">Randomize</button>
      <button id="clear">Clear All</button>
    </div>

    <div class="stats">
      <span>Generation: <b id="gen-counter">0</b></span>
      <span>Population: <b id="pop-counter">0</b></span>
    </div>

    <p class="instructions">
      Click or drag on the grid to toggle cells. 
      Watch patterns evolve according to B3/S23 rules.
    </p>
  </div>

  <script>
    // Game of Life Implementation
    const canvas = document.getElementById('life');
    const ctx = canvas.getContext('2d');

    // Configuration
    const CELL_SIZE = 10;  // Each cell is 10x10 pixels
    const GRID_WIDTH = canvas.width / CELL_SIZE;
    const GRID_HEIGHT = canvas.height / CELL_SIZE;
    const FPS = 30;

    // State variables
    let grid = createGrid();
    let nextGrid = createGrid();
    let generation = 0;
    let isPlaying = false;
    let animationId = null;

    // Mouse interaction state
    let isDrawing = false;
    let drawMode = 1; // 1 for alive, 0 for dead (when dragging)
    let mouseX = -1, mouseY = -1;

    // Create empty grid
    function createGrid() {
      return new Array(GRID_WIDTH).fill(0).map(() => new Array(GRID_HEIGHT).fill(0));
    }

    // Initialize window.life API
    window.life = {
      w: GRID_WIDTH,
      h: GRID_HEIGHT,

      get(x, y) {
        if (x < 0 || x >= GRID_WIDTH || y < 0 || y >= GRID_HEIGHT) return 0;
        return grid[x][y];
      },

      set(x, y, v) {
        if (x >= 0 && x < GRID_WIDTH && y >= 0 && y < GRID_HEIGHT) {
          grid[x][y] = v ? 1 : 0;
          draw();
        }
      },

      step() {
        // Compute next generation
        for (let x = 0; x < GRID_WIDTH; x++) {
          for (let y = 0; y < GRID_HEIGHT; y++) {
            const neighbors = countNeighbors(grid, x, y);

            // B3/S23 rules:
            // Dead cell with exactly 3 neighbors → alive
            // Live cell with 2 or 3 neighbors → alive
            if (grid[x][y] === 1 && (neighbors === 2 || neighbors === 3)) {
              nextGrid[x][y] = 1;
            } else if (grid[x][y] === 0 && neighbors === 3) {
              nextGrid[x][y] = 1;
            } else {
              nextGrid[x][y] = 0;
            }
          }
        }

        // Swap grids
        [grid, nextGrid] = [nextGrid, grid];
        generation++;

        updateStats();
        draw();
      },

      clear() {
        for (let x = 0; x < GRID_WIDTH; x++) {
          for (let y = 0; y < GRID_HEIGHT; y++) {
            grid[x][y] = 0;
          }
        }
        generation = 0;
        updateStats();
        draw();

        // Also clear the next grid to avoid any issues
        for (let x = 0; x < GRID_WIDTH; x++) {
          for (let y = 0; y < GRID_HEIGHT; y++) {
            nextGrid[x][y] = 0;
          }
        }
      },
    };

    // Count neighbors for a cell (edges are dead)
    function countNeighbors(grid, x, y) {
      let count = 0;

      // Check all 8 neighbors
      for (let i = -1; i <= 1; i++) {
        for (let j = -1; j <= 1; j++) {
          if (i === 0 && j === 0) continue;

          const nx = x + i;
          const ny = y + j;

          // Check boundaries
          if (nx >= 0 && nx < GRID_WIDTH && ny >= 0 && ny < GRID_HEIGHT) {
            count += grid[nx][ny];
          }
        }
      }

      return count;
    }

    // Draw the grid
    function draw() {
      // Clear background
      ctx.fillStyle = getComputedStyle(document.documentElement).getPropertyValue('--bg-color');
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Get current theme colors
      const aliveColor = getComputedStyle(document.documentElement).getPropertyValue('--cell-alive').trim();
      const gridLine = getComputedStyle(document.documentElement).getPropertyValue('--grid-line').trim();

      // Draw cells
      ctx.fillStyle = aliveColor;

      for (let x = 0; x < GRID_WIDTH; x++) {
        for (let y = 0; y < GRID_HEIGHT; y++) {
          if (grid[x][y] === 1) {
            ctx.fillRect(x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE - 1, CELL_SIZE - 1);
          }
        }
      }

      // Draw grid lines
      ctx.strokeStyle = gridLine;
      ctx.lineWidth = 0.5;
      ctx.beginPath();

      for (let x = 0; x <= GRID_WIDTH; x++) {
        ctx.moveTo(x * CELL_SIZE, 0);
        ctx.lineTo(x * CELL_SIZE, canvas.height);
      }

      for (let y = 0; y <= GRID_HEIGHT; y++) {
        ctx.moveTo(0, y * CELL_SIZE);
        ctx.lineTo(canvas.width, y * CELL_SIZE);
      }

      ctx.stroke();
    }

    // Update statistics display
    function updateStats() {
      const population = grid.flat().filter(cell => cell === 1).length;
      document.getElementById('gen-counter').textContent = generation;
      document.getElementById('pop-counter').textContent = population;
    }

    // Randomize the grid
    function randomize() {
      for (let x = 0; x < GRID_WIDTH; x++) {
        for (let y = 0; y < GRID_HEIGHT; y++) {
          grid[x][y] = Math.random() > 0.8 ? 1 : 0; // ~20% cells alive initially
        }
      }
      generation = 0;
      updateStats();
      draw();
    }

    // Game loop for auto-play
    function gameLoop() {
      if (isPlaying) {
        window.life.step();
        animationId = requestAnimationFrame(gameLoop);
      }
    }

    // Mouse event handlers for drawing
    function handleCanvasInteraction(e, isClick = false) {
      const rect = canvas.getBoundingClientRect();

      // Handle both mouse and touch events
      let clientX, clientY;
      if (e.touches && e.touches.length > 0) {
        clientX = e.touches[0].clientX;
        clientY = e.touches[0].clientY;
      } else {
        clientX = e.clientX;
        clientY = e.clientY;
      }

      const x = Math.floor((clientX - rect.left) * (canvas.width / rect.width) / CELL_SIZE);
      const y = Math.floor((clientY - rect.top) * (canvas.height / rect.height) / CELL_SIZE);

      // Check if the click was on a cell
      if (x >= 0 && x < GRID_WIDTH && y >= 0 && y < GRID_HEIGHT) {
        if (isClick) {
          // Toggle the clicked cell
          grid[x][y] = grid[x][y] ? 0 : 1;
          draw();
          updateStats();
        } else {
          // For dragging, set cells based on current draw mode
          if (drawMode === 1 && !grid[x][y]) {
            grid[x][y] = 1;
            draw();
            updateStats();
          } else if (drawMode === 0 && grid[x][y]) {
            grid[x][y] = 0;
            draw();
            updateStats();
          }
        }
      }
    }

    // Event listeners for canvas
    canvas.addEventListener('mousedown', e => {
      isDrawing = true;
      const rect = canvas.getBoundingClientRect();
      const x = Math.floor((e.clientX - rect.left) * (canvas.width / rect.width) / CELL_SIZE);
      const y = Math.floor((e.clientY - rect.top) * (canvas.height / rect.height) / CELL_SIZE);

      // Determine mode based on cell state: if clicked on live, draw dead; otherwise draw live
      if (x >= 0 && x < GRID_WIDTH && y >= 0 && y < GRID_HEIGHT) {
        drawMode = grid[x][y] ? 0 : 1;
        handleCanvasInteraction(e, true);
      }
    });

    canvas.addEventListener('mousemove', e => {
      if (isDrawing) {
        const rect = canvas.getBoundingClientRect();
        const x = Math.floor((e.clientX - rect.left) * (canvas.width / rect.width) / CELL_SIZE);
        const y = Math.floor((e.clientY - rect.top) * (canvas.height / rect.height) / CELL_SIZE);

        if (x >= 0 && x < GRID_WIDTH && y >= 0 && y < GRID_HEIGHT) {
          // Only update if state differs to avoid excessive redraws
          if (drawMode === 1 && !grid[x][y]) {
            grid[x][y] = 1;
            draw();
            updateStats();
          } else if (drawMode === 0 && grid[x][y]) {
            grid[x][y] = 0;
            draw();
            updateStats();
          }
        }
      }
    });

    window.addEventListener('mouseup', () => {
      isDrawing = false;
    });

    // Prevent default drag behavior
    canvas.addEventListener('dragstart', e => e.preventDefault());

    // Button event listeners
    document.getElementById('step').addEventListener('click', () => {
      window.life.step();
    });

    const playBtn = document.getElementById('play');
    playBtn.addEventListener('click', () => {
      isPlaying = !isPlaying;
      if (isPlaying) {
        playBtn.textContent = "Pause";
        playBtn.classList.add("active");
        gameLoop();
      } else {
        playBtn.textContent = "Play";
        playBtn.classList.remove("active");
        cancelAnimationFrame(animationId);
      }
    });

    document.getElementById('random').addEventListener('click', randomize);

    const clearBtn = document.getElementById('clear');
    clearBtn.addEventListener('click', () => {
      window.life.clear();
      if (isPlaying) {
        isPlaying = false;
        playBtn.textContent = "Play";
        playBtn.classList.remove("active");
        cancelAnimationFrame(animationId);
      }
    });

    // Initialize with a glider
    function initGlider() {
      const centerX = Math.floor(GRID_WIDTH / 2);
      const centerY = Math.floor(GRID_HEIGHT / 2);

      // Place a glider near the center
      grid[centerX][centerY] = 1;
      grid[centerX + 1][centerY] = 1;
      grid[centerX + 2][centerY] = 1;
      grid[centerX][centerY + 1] = 1;
      grid[centerX + 1][centerY + 2] = 1;

      draw();
    }

    // Initialize and start
    initGlider();

    // Add a few more interesting starting patterns for fun
    function addBlock() {
      const x = 5, y = 5;
      grid[x][y] = 1;
      grid[x + 1][y] = 1;
      grid[x][y + 1] = 1;
      grid[x + 1][y + 1] = 1;
    }

    function addBlinker() {
      const x = Math.floor(GRID_WIDTH / 2);
      const y = Math.floor(GRID_HEIGHT / 2) + 10;

      grid[x][y] = 1;
      grid[x - 1][y] = 1;
      grid[x + 1][y] = 1;
    }

    addBlock();
    addBlinker();

    // Final draw to show everything
    updateStats();
    draw();
  </script>
</body>
</html>
